		"icon_huijuandaoju_01",
		0,
		999,
		999,
		false,
		0,
		false,
		true,
		0,
		"",
		"剧情碎片之一：\r\n我生在众人穷尽一生，都无法踏入的地方。\r\n这里洁净、神圣、高雅……还有无知者向往的和平。\r\n然而，维持众神和平的议事之地，从来就不存在和平。\r\n那些残酷的血肉，都藏在他们的笑脸中——我看到了，也学会了。",
		"",
		0,
		""
	},
	{
		1219,
		82001758,
		0,
		3,
		"icon_huijuandaoju_02",
		0,
		999,
		999,
		false,
		0,
		false,
		true,
		0,
		"",
		"剧情碎片之一：\r\n“达克诺斯，你还是太弱了。”\r\n父亲，我会更努力修炼，请给我一些时间。\r\n“达克诺斯，你太让我失望了。”\r\n父亲，我差一点就能做到了……\r\n“达克诺斯，我怎么会有你这样的儿子。”\r\n我……也不想成为主祭的孩子。",
		"",
		0,
		""
	},
	{
		1220,
		82001759,
		0,
		3,
		"icon_huijuandaoju_03",
		0,
		999,
		999,
		false,
		0,
		false,
		true,
		0,
		"",
		"剧情碎片之一：\r\n“主祭的继任者虽然聪明，但实力比起少年时的主祭还差了一些。”\r\n明明把所有的时间都花在修炼上了……为什么还不够强……\r\n“幼子是圣洁之体，如果能放到长子身上……”\r\n同样是父亲的血脉，为什么我就没有这样的天赋？\r\n明明我才是长子，明明我才是神殿的继承人……\r\n可不管我再努力，也比不上那天赋……",
		"",
		0,
		""
	},
	{
		1221,
		82001760,
		0,
		3,
		"icon_huijuandaoju_04",
		0,
		999,
		999,
		false,
		0,
		false,
		true,
		0,
		"",
		"剧情碎片之一：\r\n“哥哥快看，我学会新魔法了！”\r\n看着萨拉天真的笑容，我心中涌现的是怒气、嫉妒，或许还有无措、恐惧。\r\n我是他的兄长，该包容他、原谅他、保护他……\r\n可是他无知的神情，真的太令人讨厌了。",
		"",
		0,
		""
	},
	{
		1222,
		82001761,
		0,
		3,
		"icon_huijuandaoju_05",
		0,
		999,
		999,
		false,
		0,
		false,
		true,
		0,
		"",
		"剧情碎片之一：\r\n第一眼我就被它深深吸引了。\r\n这座崇尚白魔法的神殿中，居然藏着一本黑魔法书。\r\n神秘、强大的气息，让我情不自禁解开封印，翻开那残破的书页……\r\n“我的主人，黑魔法能为你实现所愿……”\r\n被神殿禁止的黑魔法……可又怎么样呢？只要它能让我获得力量……",
		"",
		0,
		""
	},
	{
		1223,
		82001762,
		0,
		3,
		"icon_huijuandaoju_06",
		0,
		999,
		999,
		false,
		0,
		false,
		true,
		0,
		"",
		"剧情碎片之一：\r\n必须把这本黑魔法禁书藏起来……\r\n那就藏到脑袋后，成为我的第三只眼睛吧。\r\n“不……魂器重塑是高等黑魔法，你怎么会！”\r\n这是从你身上学会的……\r\n黑魔法，比我想象中更简单呢……",
		"",
		0,
		""
	},
	{
		1224,
		82001763,
		0,
		3,
		"icon_huijuandaoju_07",
		0,
		999,
		999,
		false,
		0,
		false,
		true,
		0,
		"",
		"剧情碎片之一：\r\n百利圣木的叶子化成利刃，落下时划破我的皮肤，一片又一片……血液凝聚在树下，成为了这棵圣木的养分。\r\n“哥哥，你快跟主祭认错吧，不然祭司们要把你驱逐出神殿了！”\r\n错？我没有错。我只是遵循大家的愿望，努力变强。\r\n既然黑魔法比白魔法更强大，为什么不能学习呢……",
		"",
		0,
		""
	},
	{
		1225,
		82001764,
		0,
		3,
		"icon_huijuandaoju_08",
		0,
		999,
		999,
		false,
		0,
		false,
		true,
		0,
		"",
		"剧情碎片之一：\r\n“我以神殿主祭之令布下神喻，达克诺斯触犯神律，将永久驱逐出神殿。”\r\n“为什么要把哥哥赶走？”\r\n“萨拉，他不是你的哥哥，圣地亚的姓氏他也不配拥有。”\r\n“这里不是肮脏的流浪者该出现的地方，立刻离开！”\r\n我以灵魂起誓，未来我将再次踏入此地——以领神的身份。",
		"",
		0,
		""
	},
	{
