		0,
		false,
		true,
		0,
		"",
		"剧情碎片之一：\r\n“达克诺斯被驱逐了，谁也不敢得罪神殿收留他，他要成为流浪者了吧。”\r\n“真可怜，从尊贵的神殿继任者到落魄的流浪者。”\r\n可怜？不，我只是自由了。\r\n即使迎接我的将是苦难、欺诈、折磨……\r\n但既然黑暗要把我吞噬，那我便化身黑暗。",
