		0,
		3,
		"icon_huijuandaoju_10",
		0,
		999,
		999,
		false,
		0,
		false,
		true,
		0,
		"",
		"自古以来龙族的诞生一直是个谜团。\r\n祂们因何而生，为何而亡？是世宇规则的具象化身还是无上意志的代行之神？\r\n在重重谜题前，唯一所明晰的是祂们守护所珍视之物的决心，从不容他人染指沾污……\r\n而这次，源自深渊不绝的龙吼亦在佐证着这一点：龙皇对夺青之胜的势在必得。",
		"",
		0,
		""
	},
	{
		1260,
		82001796,
		0,
		3,
		"icon_huijuandaoju_11",
		0,
		999,
		999,
		false,
		0,
		false,
		true,
		0,
		"",
		"“赶紧跟上，诺亚！不要偷懒！”\r\n不知为什么，总感觉现在的修尔与以往有些不同。\r\n“修尔，今天的训练量应该够了吧？”\r\n眼前是一排高耸入云的梅花桩，木桩一节更比一节高，看不清终点也看不见尽头……\r\n“别想偷懒，这么懈怠，我们怎么赢得过赤焰龙皇？”\r\n看来……不得不使出那招了——时间凝滞！",
		"",
		0,
		""
	},
	{
		1261,
		82001797,
		0,
		3,
		"icon_huijuandaoju_12",
		0,
		999,
		999,
		false,
		0,
		false,
		true,
		0,
		"",
		"“你问我赤焰龙皇为什么会把天青认成夜昙？”\r\n“嗯……从目前掌握的数据来看，要想接近龙族，摸清祂们习性是十分必要的事情，所以这次的核心提炼了很多相关数据……”\r\n“目前看来成效斐然……在你眼中它可能只是一颗大青菜，但在其他人眼中可能是其最渴望的事物……”\r\n“你又问我为什么要抢一个大青菜？嘿嘿嘿，因为数据太过庞杂，如果让其他人抢到的话后果不堪设想……没事！最坏的后果也不过是被困在战场里面出不来而已嘛……”",
		"",
		0,
		""
	},
	{
		1262,
		82001798,
		0,
		3,
		"icon_huijuandaoju_13",
		0,
		999,
		999,
		false,
		0,
		false,
		true,
		0,
		"",
		"“天青寓意祥瑞吉兆，抬着狮头对其进行包括但不限于、惊、吞吐等动作来表现醒狮灵巧机敏的神态神韵，通过一系列醒狮的采青表演来赢得来年顺遂平安的好彩头。”\r\n“年关将至，每年这个特殊的时节在曙光森林采摘的天青结印，蕴含特殊且充沛的生命力量，令人艳羡的宝物背后，可是长老们和阿瑞细心栽育努力培养的宝贵结晶哦~”\r\n诺亚在众人面前滔滔不绝的讲解，好不风光。\r\n“你说的很好，但谁能来解释一下为什么我们抢青的对手是赤焰龙皇？”\r\n“……”",
		"",
		0,
		""
	},
	{
		1263,
		82001799,
		0,
		3,
		"icon_huijuandaoju_14",
		0,
		999,
		999,
		false,
		0,
		false,
		true,
		0,
		"",
		"活灵活现的醒狮变得萎靡不振，刚刚制作的狮头更是毫无灵气可言。\r\n“怎么会这样呢，总感觉穿上这身装备舞动起来一点精气神都没有。”\r\n诺亚丧气的靠在修尔身旁，一边叹气一边打量着眼前的狮头。\r\n“诺亚，你老实告诉我，你是从哪拿的这个狮头？”\r\n“老师傅的工台案板上……”\r\n话音未落便迎面挨了修尔一个栗暴,手中狮子的双目俏皮地眨起了眼睛……",
		"",
		0,
		""
	},
	{
		1264,
		82001800,
		0,
		3,
		"icon_huijuandaoju_15",
		0,
		999,
		999,
		false,
		0,
		false,
		true,
		0,
		"",
		"“要么低头臣服，要么化为尘土！”\r\n旷古龙鸣不绝于耳，令人颓废丧胆的余音击穿了每一个参赛者的意志。\r\n“我就是要让这绝望的薪火燃烬每一寸土地！这才是我的本质！”\r\n“我是永不断绝的恶，魔界深渊的皇！”",
		"",
		0,
		""
	},
	{
		1265,
		82001801,
		0,
		3,
		"icon_huijuandaoju_16",
		0,
		999,
		999,
		false,
		0,
		false,
		true,
		0,
		"",
		"常人眼中，它代表世事的夙愿，不解之梦，未明之缘。\r\n它可以变幻为任何事物亦可为任何人满足其欲望，是万能的许愿机。\r\n它诞生在恶土之上，浇灌仇恨、贪婪、背叛和不计其数的罪业与欲望……\r\n但在龙皇眼中，它只是一朵洁白的小花。",
		"",
		0,
		""
	},
	{
		1266,
		82001802,
		0,
		3,
		"icon_huijuandaoju_17",
		0,
		999,
		999,
		false,
		0,
		false,
		true,
		0,
		"",
		"“喜、怒、哀、乐、动、静、惊、疑，要牢记这几点，虽然你们是新手，但也要尽可能的在一次舞狮表演中全部展现出来！”\r\n修尔与诺亚在台阶下认真地聆听着大师傅的教诲。\r\n“哎，这几个动作也太难了……”\r\n“那如果我直接跳过这些流程，直接夺青呢？”\r\n“……”\r\n夕阳下，操场上，修尔与诺亚的背景渐行渐远……然后又渐近。\r\n“臭小子，按圈跑！”",
		"",
		0,
		""
	},
	{
		1267,
		82001803,
		0,
		3,
		"icon_huijuandaoju_18",
		0,
		999,
		999,
		false,
		0,
		false,
		true,
		0,
		"",
		"“本次舞狮大赛由神秘人士斥资赞助举办，出手阔绰，预算充足，甚至一手包办了大赛的后勤工作！为了感谢她的慷慨解囊，现在有请舞狮队员代表修尔和诺亚同赞助人一起为大赛揭幕！”\r\n修尔和诺亚在众人羡慕的目光注视下地上台，与兴致高昂的赞助人一同为大赛揭幕。\r\n“哎？这个福字怎么贴倒了？”\r\n“笨啊你，福倒了，福到了！这取的可是同音异义的好兆头！”\r\n“可不止是倒了呀，这个福字还左右翻转了！”\r\n熙熙攘攘的人群中杂音四起，修尔和诺亚面面相觑，异口同声。\r\n“是他干的！”\r\n无人看到的角落，赞助人悄悄收起了手中的剪刀……",
